import time

class MiniTestRunner:
    def __init__(self):
        self.tests = []
    def add(self, fn):
        self.tests.append(fn)
    def run_all(self):
        passed, failed = 0, []
        t0 = time.perf_counter()
        for test in self.tests:
            try:
                test()
                passed += 1
            except AssertionError as err:
                failed.append((test.__name__, str(err)))
        elapsed = time.perf_counter() - t0
        print(f"📊 Test Summary: {passed} Passed, {len(failed)} Failed in {elapsed:.4f}s")
        if failed:
            print("  ❌ Failures:", failed)
        else:
            print("  ✨ All regression checks green!")

