class FastAPISimulator:
    def __init__(self, title: str):
        self.title = title
        self.routes = {}

    def get(self, path: str):
        def decorator(func):
            self.routes[('GET', path)] = func
            return func
        return decorator

    def post(self, path: str):
        def decorator(func):
            self.routes[('POST', path)] = func
            return func
        return decorator

    def dispatch(self, method: str, path: str, payload: dict = None):
        handler = self.routes.get((method.upper(), path))
        if not handler:
            return {"status": 404, "error": f"Route {method} {path} not found"}
        return {"status": 200, "data": handler(payload) if payload else handler()}

app = FastAPISimulator("AI Prediction Microservice")

