def predict(data):
    prompt = data.get("prompt", "")
    return {"prompt": prompt, "tokens": len(prompt.split()), "sentiment": "POSITIVE"}

print("🚀 FastAPI App Routes Registered:", list(app.routes.keys()))
print("\n1. Dispatch GET /health:")
print("  Response:", app.dispatch("GET", "/health"))

