import asyncio, inspect

class PubSubBroker:
    def __init__(self):
        self.channels = {}
    def subscribe(self, topic: str, callback):
        self.channels.setdefault(topic, set()).add(callback)
    async def broadcast(self, topic: str, message: str):
        listeners = self.channels.get(topic, set())
        tasks = []
        for cb in listeners:
            if inspect.iscoroutinefunction(cb):
                tasks.append(cb(message))
            else:
                # Wrap sync callback into an awaitable task
                async def _sync_wrap(fn=cb, msg=message):
                    return fn(msg)
                tasks.append(_sync_wrap())
        return await asyncio.gather(*tasks) if tasks else []

async def main():
    broker = PubSubBroker()
    async def client_a(msg):
        return f"Client A (WebSocket) received: {msg}"
    def client_b(msg):
        return f"Client B (Logger) recorded: {msg}"

    broker.subscribe("telemetry", client_a)
    broker.subscribe("telemetry", client_b)

    responses = await broker.broadcast("telemetry", "Epoch 10 Accuracy 99.1%")
    for r in responses:
        print("  Broadcast ->", r)

try:
    asyncio.run(main())
except RuntimeError:
    import asyncio, inspect
    asyncio.create_task(main())
